"""Module for test control CLI validations"""
import json
from datetime import datetime
from pathlib import Path
from typing import Any

from marvin_client.exceptions import ValidationException

SUPPORTED_OPERATIONS_AND_OBJECT_TYPES = {
    "create": ["test_run", "test_case", "test_step"],
    "update": ["test_run", "test_case", "test_step", "test_line"],
    "start": ["test_run", "test_case", "test_step"],
    "stop": ["test_run", "test_case", "test_step"],
}


def validate_json_data(json_data: str) -> dict:
    """
    Validate JSON string.
    :param json_data: JSON data to validate
    :return: Parsed data
    :raise ValidationException: Raised when there is no data or JSON parsing fails.
    """
    if not json_data:
        raise ValidationException("Empty JSON data")

    try:
        data = json.loads(json_data)
    except Exception as ex:
        raise ValidationException(f"Failed to parse JSON data: {str(ex)}")

    if not data:
        raise ValidationException("Empty JSON data")

    if not data.get("meta") or not data["meta"].get("bts_id"):
        raise ValidationException("Parameter 'meta.bts_id' is missing in JSON data")

    return data


def validate_json_file(json_file: Path) -> dict:
    """
    Validate JSON file.
    :param json_file: JSON file path
    :return: Parsed data
    :raise ValidationException: Raised when there the file does not exist, there is no data or JSON parsing fails.
    """
    if not json_file.exists():
        raise ValidationException(f"JSON file does not exist: {str(json_file)}")

    try:
        json_str = json_file.read_text()
    except Exception as ex:
        raise ValidationException(f"Failed to read JSON file: {str(ex)}")

    return validate_json_data(json_str)


def validate_datetime_str(datetime_str: str, name: str) -> None:
    """
    Validate datetime string is not empty and is in UTC time.
    Format has to be "%Y-%m-%dT%H:%M:%S.%fZ".

    :param datetime_str: Datetime to validate
    :param name: Parameter name. Used only in validation exception message.
    :raise ValidationException: Raised when there the datetime string is empty or does not end with "Z" character.
    """
    if not datetime_str:
        raise ValidationException(f"Parameter '{name}' is empty")

    try:
        datetime.strptime(datetime_str, "%Y-%m-%dT%H:%M:%S.%fZ")
    except Exception:
        raise ValidationException(
            f"Parameter '{name}' is in incorrect format. It must be UTC time in format '%Y-%m-%dT%H:%M:%S.%fZ'"
        ) from None  # Prevent chaining original exception


def validate_not_empty(value: Any, name: str) -> None:
    """
    Validate any value is not empty or null.

    :param value: Value to validate
    :param name: Parameter name. Used only in validation exception message.
    :raise ValidationException: Raised when there test `if not value' is True.
    """
    if not value:
        raise ValidationException(f"Parameter '{name}' is empty")


def validate_object_type(command: str, object_data: dict) -> str:
    """
    Validate object type in the object data is supported for the command.

    :param command: Command, e.g. "create", "update"
    :param object_data: Object data
    :return: Object type, e.g. "test_run", "test_case"
    :raise ValidationException: Raised when object type is not supported for the given command.
    """
    supported_objects = SUPPORTED_OPERATIONS_AND_OBJECT_TYPES[command]

    for param_name in object_data:
        if param_name in supported_objects:
            return param_name

    raise ValidationException(f"Unsupported object type in object data for command '{command}'")
